<?php /** 출퇴근 요청 저장 */
use App\Core\Db; require_once __DIR__.'/common.php'; if($_SERVER['REQUEST_METHOD']!=='POST'||!csrf_check(isset($_POST['_csrf'])?$_POST['_csrf']:'')){flash_set('danger','잘못된 요청입니다.');header('Location: ?r=대시보드');exit;} $pdo=Db::pdo();$eid=attendance_employee_id($pdo);$d=trim((string)$_POST['request_date']);$t=trim((string)$_POST['request_type']);$ci=trim((string)$_POST['requested_check_in']);$co=trim((string)$_POST['requested_check_out']);$reason=trim((string)$_POST['reason']);$now=attendance_now(); try{$st=$pdo->prepare("INSERT INTO cpms_attendance_requests(employee_id,request_date,request_type,requested_check_in,requested_check_out,reason,status,created_at,updated_at) VALUES(:e,:d,:t,:ci,:co,:r,'pending',:c,:u)");$st->execute(array(':e'=>$eid,':d'=>$d,':t'=>$t,':ci'=>$ci?:null,':co'=>$co?:null,':r'=>$reason,':c'=>$now,':u'=>$now));flash_set('success','출퇴근 수정 요청이 등록되었습니다.');}catch(Exception $e){flash_set('danger','요청 저장 실패');} header('Location: ?r=대시보드');